# The IWRAM image's code (ldscript.txt's `iwram` section): linked to run
# at 0x03000000 and stored in ROM at IWRAM_LMA. Same layout as UNITS, but
# the addresses are IWRAM (run) addresses and the targets are sliced from
# expected/iwram.s, the frozen ARM disassembly of the image - see
# docs/decomp_dev.md's "The IWRAM image". Its initialised data
# (src/iwram/iwram_data.cpp) is a data unit, see IWRAM_DATA below.
IWRAM_CODE = ROOT / "expected" / "iwram.s"
IWRAM_UNITS = [
    (0x03000000, HANDWRITTEN, None),  # IntrMain (asm/intr_main.s), the interrupt dispatcher - hand-written ARM, excluded from progress
    (0x030000D4, "src/iwram/string_arm.o", "util"),  # strlen_arm/strcpy_arm/strncpy_arm/strcat_arm/itoa_arm (C++, ARM, agbcp_arm_patched -mleaf-no-lr-save, no scheduling) - docs/matching/iwram-image.md
    (0x0300024C, "src/iwram/sprite_arm.o", "graphics"),  # UnpackNibbleTiles/DrawMirroredTilemap/HeapSortActorsByKey/UnpackRleSpriteFrame/LookupSpriteFrameCache (C++, ARM, agbcp_arm_patched -minterwork-return-lr) - docs/matching/iwram-image.md
    (0x030007CC, None, None),  # sentinel: the image's initialised data starts here
]

# Display names for progress_categories - report_units.py-only categories
# (game_loop/actor/... don't mirror a src/ directory the way graphics/util/
# system do, so `category.capitalize()` alone would read oddly).
CATEGORY_NAMES = {
    "system": "System",
    "util": "Util",
    "graphics": "Graphics",
    "game_loop": "Game Loop",
    "actor": "Actor",
    "graphics_loading": "Graphics Loading",
    "audio": "Audio",
    "gax": "GAX2 sound engine (lib)",
    "agb_eeprom": "AgbEeprom SDK (lib)",
    "libgcc": "libgcc (lib)",
    "hud": "HUD",
    "overlay_ui": "Overlay UI",
    "data": "Data",
}


def run(cmd, **kwargs):
    subprocess.run(cmd, check=True, **kwargs)


def resolved_callees():
    """`resolve NAME` entries in expected/corrections.txt - see
    slice_expected.py for what they do."""
    names = []
    for line in CORRECTIONS.read_text().splitlines():
        parts = line.split("#", 1)[0].split()
        if len(parts) == 2 and parts[0] == "resolve":
            names.append(parts[1])
    return names


def slice_source(source, start, end):
    args = ["python3", str(ROOT / "tools" / "slice_expected.py"),
            *(f"--resolve={name}" for name in resolved_callees()), str(source), f"{start:x}"]
    if end is not None:
        args.append(f"{end:x}")
    return subprocess.run(args, capture_output=True, text=True, check=True).stdout


def build_target(name, start, end, source=None):
    """Assembles the frozen-source slice(s) covering [start, end) into
    build/expected/units/<key>_target.o, applying corrections.txt.
    `source` overrides the frozen file (expected/iwram.s for the IWRAM
    units); by default it is expected/legacy.s and/or expected/code_3.s.

    Filenames are keyed by `name` plus `start` (not `name` alone): several
    UNITS entries intentionally share one base_object (e.g. two matched
    functions split out of the same .c file, each with its own address
    range - see save_data.o/starfield.o) and used to collide on
    plain `{name}_target.o`, silently overwriting each other's expected
    bytes so only the last such entry's function was ever actually
    objdiff-verified. """
    key = f"{name}_{start:08X}"
    out_o = BUILD_DIR / f"{key}_target.o"
    if source is not None:
        text = slice_source(source, start, end)
        out_s = BUILD_DIR / f"{key}_target.s"
        out_s.write_text(text)
        run(AS + ["-o", str(out_o), str(out_s)])
    elif start < CODE3_START and (end is None or end <= CODE3_START):
        text = slice_source(LEGACY, start, end)
        out_s = BUILD_DIR / f"{key}_target.s"
        out_s.write_text(text)
        run(AS + ["-o", str(out_o), str(out_s)])
    elif start >= CODE3_START:
        text = slice_source(CODE3, start, end)
        out_s = BUILD_DIR / f"{key}_target.s"
        out_s.write_text(text)
        run(AS + ["-o", str(out_o), str(out_s)])
    else:
        # Straddles both frozen sources (only irq.cpp does) - slice each
        # half separately, then merge.
        legacy_text = slice_source(LEGACY, start, CODE3_START)
        code3_text = slice_source(CODE3, CODE3_START, end)
        legacy_s = BUILD_DIR / f"{key}_legacy.s"
        code3_s = BUILD_DIR / f"{key}_code3.s"
        legacy_s.write_text(legacy_text)
        code3_s.write_text(code3_text)
        legacy_o = BUILD_DIR / f"{key}_legacy.o"
        code3_o = BUILD_DIR / f"{key}_code3.o"
        run(AS + ["-o", str(legacy_o), str(legacy_s)])
        run(AS + ["-o", str(code3_o), str(code3_s)])
        run(LD + ["-o", str(out_o), str(legacy_o), str(code3_o)])

    run(["python3", str(ROOT / "tools" / "patch_expected_target.py"), str(CORRECTIONS), str(out_o)])
    return out_o


#### Data units (decomp.dev's separate "data" progress bar) ####
#
# Everything from DATA_START to the end of the ROM is linked from the
# "/* Data */" block of ldscript.txt, in ROM order: the sections of
# data/data.s (one label per blob, each blob a single `.incbin`)
# interleaved with the `.rodata` of the C data objects under src/data/
# (see docs/data.md). A blob is "matched" when it is built from a source
# in the repo (graphics compressed from a PNG, the GAX2 audio rebuilt from
# .xm/.wav, the sfx table from JSON, a src/data C table, ...) and
# "unmatched" while it's still `.incbin "baserom.gba"`. Both give identical
# bytes, so an honest data measure can't come from diffing bytes alone:
# baserom-copied blobs get a target symbol but no base symbol, exactly like
# the still-raw code ranges above. See docs/decomp_dev.md's "Data progress".

DATA_S = ROOT / "data" / "data.s"
LDSCRIPT = ROOT / "ldscript.txt"
OBJ_ROOT = "build/crashbandicootxs"
DATA_BUILD_DIR = BUILD_DIR / "data"
BASEROM = ROOT / "baserom.gba"
ROM_BASE = 0x08000000
DATA_START = UNITS[-1][0]  # the data is linked straight after the last code unit
DATA_CATEGORY = "data"
# Start of the ROM's trailing 0xFF cartridge filler (runs to 0x08800000);
# see trim_rom_filler().
DATA_END = 0x087E5FCC
# The IWRAM image (ldscript.txt's `iwram` section) is stored in ROM from
# IWRAM_LMA, right after the "/* Data */" block. Its code is counted as
# code (IWRAM_UNITS); its initialised data, src/iwram/iwram_data.cpp's
# .data, is the last data unit, at IWRAM_LMA + (its IWRAM offset).
IWRAM_LMA = 0x087E55E4
IWRAM_DATA = ("src/iwram/iwram_data.o", ".data", IWRAM_LMA + IWRAM_UNITS[-1][0] - 0x03000000)


def data_layout():
    """(object, section) pairs of ldscript.txt's "/* Data */" block, in
    link (= ROM) order, e.g. ("data/data.o", ".rodata.0816C090") or
    ("src/data/action_table_16bf20.o", ".rodata")."""
    block = LDSCRIPT.read_text().split("/* Data */", 1)[1].split("}", 1)[0]
    return re.findall(rf"{OBJ_ROOT}/(\S+?\.o)\((\S+?)\);", block)


def parse_data_s():
    """data.s's blobs, grouped by section: {section: [blob, ...]}. Each
    blob is a dict with the label name, size, the incbin's path/offset/
    length, and `built` (False when the bytes are copied from
    baserom.gba). parse_data() fills in the addresses."""
    sections = {".rodata": []}
    blobs = sections[".rodata"]
    started = set()
    name = None
    for lineno, line in enumerate(DATA_S.read_text().splitlines(), 1):
        s = line.split("@", 1)[0].strip()
        if not s or s.startswith(".global"):
            continue
        if s.startswith(".section"):
            sec = s.split()[1].rstrip(",")
            if sec in started:
                sys.exit(f"{DATA_S}:{lineno}: section {sec} is started twice")
            started.add(sec)
            blobs = sections.setdefault(sec, [])
            continue
        m = re.fullmatch(r"(\w+):", s)
        if m:
            name = m.group(1)
            continue
        m = re.fullmatch(r'\.incbin\s+"([^"]+)"(?:\s*,\s*(\w+)\s*,\s*(\w+))?', s)
        if not m or name is None:
            sys.exit(f"{DATA_S}:{lineno}: unsupported line for the data report: {s!r}")
        path, off, length = m.group(1), m.group(2), m.group(3)
        if length is not None:
            size = int(length, 0)
        else:
            src = ROOT / path
            if not src.exists():
                sys.exit(f"{src} missing - build the data assets first (`make report` does)")
            size = src.stat().st_size
        blobs.append({"name": name, "size": size, "path": path, "off": off,
                      "len": length, "built": path != "baserom.gba", "lineno": lineno})
        name = None  # one incbin per label - a second one would need a symbol
    return sections


def c_data_blobs(obj, section):
    """One blob per global object symbol in `section` of a src/data C
    object (or a C++ object's g++-emitted vtable, whose symbol is weak),
    in address order, plus the section's alignment. A blob runs to the
    next symbol (or the section's end), so alignment padding between two
    tables counts toward the first."""
    path = ROOT / OBJ_ROOT / obj
    if not path.exists():
        sys.exit(f"{path} missing - build it first (`make report` does)")
    headers = subprocess.run(["arm-none-eabi-objdump", "-h", str(path)],
                             capture_output=True, text=True, check=True).stdout
    m = re.search(rf"^\s*\d+\s+{re.escape(section)}\s+([0-9a-f]+)(?:\s+[0-9a-f]+){{3}}\s+2\*\*(\d+)$",
                  headers, re.M)
    if not m:
        sys.exit(f"{obj} has no {section} section")
    sec_size, align = int(m.group(1), 16), 1 << int(m.group(2))
    table = subprocess.run(["arm-none-eabi-objdump", "-t", str(path)],
                           capture_output=True, text=True, check=True).stdout
    syms = []
    for line in table.splitlines():
        # "00000000 g     O .rodata\t00000150 gActionCtrlStateTable"
        f = re.match(r"([0-9a-f]{8}) (.{7}) (\S+)\t[0-9a-f]+ (\S+)$", line)
        # (a weak one, "00000000  w    O ...", for a g++-emitted vtable)
        if f and f.group(3) == section and (f.group(2)[0] == "g" or f.group(2)[1] == "w") \
                and f.group(2)[6] == "O":
            syms.append((int(f.group(1), 16), f.group(4)))
    syms.sort()
    if not syms or syms[0][0] != 0:
        sys.exit(f"{obj}: {section} must start with a global object symbol")
    source = obj[:-2] + (".cpp" if (ROOT / (obj[:-2] + ".cpp")).exists() else ".c")
    blobs = []
    for i, (value, name) in enumerate(syms):
        end = syms[i + 1][0] if i + 1 < len(syms) else sec_size
        blobs.append({"name": name, "size": end - value, "path": source,
                      "off": None, "len": None, "built": True, "c_source": True})
    return blobs, align


def parse_data():
    """Returns one dict per data blob, in ROM order, with its address:
    data.s's sections and the src/data C objects' tables, laid out the
    way ldscript.txt links them. A baserom blob's own incbin offset must
    agree with the computed address, which catches any drift between
    this parser and the real layout (a C table of the wrong size
    included)."""
    sections = parse_data_s()
    blobs = []
    addr = DATA_START
    for obj, section in data_layout():
        if obj == "data/data.o":
            if section not in sections:
                sys.exit(f"ldscript.txt links data.o({section}), which data/data.s doesn't define")
            part, align = sections.pop(section), 1
        elif obj.startswith("src/data/") or re.match(r"lib/\w+/data/", obj):
            part, align = c_data_blobs(obj, section)
        elif obj.startswith("src/") and section.startswith(".gnu.linkonce.d._vt."):
            # a vtable g++ emitted in its class's key-method object
            # (docs/cplusplus.md, "Emitting the vtables")
            part, align = c_data_blobs(obj, section)
        else:
            sys.exit(f"ldscript.txt: unexpected object {obj} in the data block")
        if addr % align:
            sys.exit(f"{obj}({section}) needs {align}-byte alignment but would start at {addr:#x}")
        for blob in part:
            blob["addr"] = addr
            if not blob["built"] and int(blob["off"], 0) != addr - ROM_BASE:
                sys.exit(f"{DATA_S}:{blob['lineno']}: {blob['name']} is at {addr:#x} "
                         f"but incbins offset {blob['off']}")
            addr += blob["size"]
            blobs.append(blob)
    if sections:
        sys.exit(f"data/data.s sections not linked by ldscript.txt: {', '.join(sections)}")
    if addr != IWRAM_LMA:
        sys.exit(f"the data block ends at {addr:#x}, not at the IWRAM image ({IWRAM_LMA:#x})")
    obj, section, addr = IWRAM_DATA
    part, align = c_data_blobs(obj, section)
    if addr % align:
        sys.exit(f"{obj}({section}) needs {align}-byte alignment but would start at {addr:#x}")
    for blob in part:
        blob["addr"] = addr
        addr += blob["size"]
        blobs.append(blob)
    return blobs


def blob_group(blob):
    """Asset directory a built blob comes from (e.g. graphics/intro), the
    source file minus `.c` for a src/data table (each C file is its own
    unit) or minus `.cpp` for a g++-emitted vtable, None for a baserom
    blob."""
    if not blob["built"]:
        return None
    if blob.get("c_source"):
        return str(Path(blob["path"]).with_suffix(""))
    return str(Path(blob["path"]).parent.relative_to("build/crashbandicootxs"))


def group_data_blobs(blobs):
    """Splits the blobs into units: each maximal run of adjacent blobs
    built from the same asset directory, and each maximal run of adjacent
    baserom blobs. Units are never mixed: objdiff's report measures data
    per section and all or nothing (a section counts as matched only at
    100%), and it merges `.rodata.*` sections back into one `.rodata` per
    object, so a baserom blob inside a unit would zero out every built blob
    next to it. Keeping units pure makes each one simply 0% or 100%."""
    runs = []
    for blob in blobs:
        g = blob_group(blob)
        if runs and runs[-1]["group"] == g:
            runs[-1]["blobs"].append(blob)
        else:
            runs.append({"group": g, "blobs": [blob]})
    return runs


def incbin_line(blob, from_rom):
    if blob.get("c_source"):
        # A src/data table's bytes only exist after linking (its pointers
        # are relocations), and `make report` doesn't link. `make compare`
        # already proves them equal to the ROM's, so the base reuses the
        # ROM bytes (zero fill when there's no ROM - the target does too).
        from_rom = BASEROM.exists()
        if not from_rom:
            return f"\t.space {blob['size']:#x}\n"
    if from_rom:
        return f'\t.incbin "baserom.gba", {blob["addr"] - ROM_BASE:#x}, {blob["size"]:#x}\n'
    if blob["len"] is not None:
        return f'\t.incbin "{blob["path"]}", {blob["off"]}, {blob["len"]}\n'
    return f'\t.incbin "{blob["path"]}"\n'


def write_data_object(out_o, blobs, body):
    """Assembles `blobs` back to back as sized, global data objects in
    .rodata, each one's bytes given by body(blob)."""
    text = ".section .rodata\n"
    for blob in blobs:
        n = blob["name"]
        text += f"\n.global {n}\n.type {n}, %object\n{n}:\n{body(blob)}.size {n}, {blob['size']:#x}\n"
    out_s = out_o.with_suffix(".s")
    out_s.write_text(text)
    run(AS + ["-o", str(out_o), str(out_s)], cwd=ROOT)
    return out_o


def trim_rom_filler(blobs, have_rom):
    """Drops the cartridge's trailing 0xFF filler from the data range.

    Everything from DATA_END (the end of the IWRAM image) to the end of the
    8 MB ROM is 0xFF fill (ldscript.txt's rom_fill section): empty ROM
    space, not data, so it shouldn't count toward total_data. No blob
    reaches it any more; the check stays as a guard. DATA_END is a
    constant so the fork-PR path (no baserom.gba) gets the same totals; when
    the ROM is there, it's checked to really be where the trailing 0xFF run
    starts."""
    if have_rom:
        rom = BASEROM.read_bytes()
        end = DATA_END - ROM_BASE
        if rom[end:].strip(b"\xff") or rom[end - 1] == 0xFF:
            sys.exit(f"DATA_END {DATA_END:#x} is not the start of baserom.gba's trailing 0xFF filler")
    out = []
    for blob in blobs:
        if blob["addr"] >= DATA_END:
            continue
        if blob["addr"] + blob["size"] > DATA_END:
            if blob["built"]:
                sys.exit(f"{blob['name']} is built from a source but overlaps the trailing filler")
            blob = dict(blob, size=DATA_END - blob["addr"])
        out.append(blob)
    return out


def data_units():
    """objdiff units for the data (data/data.s and src/data - see the
    comment above DATA_S)."""
    DATA_BUILD_DIR.mkdir(parents=True, exist_ok=True)
    have_rom = BASEROM.exists()
    if not have_rom:
        # Fork-PR CI has no ROM. Raw targets only need the right size
        # (they have no base to compare against); built ones fall back to
        # their own bytes, which main's `make compare` verifies anyway.
        print("warning: baserom.gba missing - data targets use built bytes/zero fill", file=sys.stderr)

    def target_body(blob):
        if have_rom:
            return incbin_line(blob, True)
        return incbin_line(blob, False) if blob["built"] else f"\t.space {blob['size']:#x}\n"

    units = []
    for run_ in group_data_blobs(trim_rom_filler(parse_data(), have_rom)):
        blobs = run_["blobs"]
        start = blobs[0]["addr"]
        tag = run_["group"].replace("/", "_") if run_["group"] else "raw"
        name = f"data_{tag}_{start:08X}"
        unit = {
            "name": name,
            "target_path": str(write_data_object(
                DATA_BUILD_DIR / f"{name}_target.o", blobs, target_body).relative_to(ROOT)),
        }
        metadata = {"progress_categories": [DATA_CATEGORY]}
        if run_["group"] is not None:
            unit["base_path"] = str(write_data_object(
                DATA_BUILD_DIR / f"{name}_base.o", blobs,
                lambda b: incbin_line(b, False)).relative_to(ROOT))
            # built from an editable source, so nothing left to clean up
            metadata["complete"] = True
        unit["metadata"] = metadata
        units.append(unit)
    return units


def build_base(name, start, base_rel):
    """Copies a unit's compiled object to build/expected/units/<key>_base.o
    and widens any function size that stops short of the next function
    (an inline-asm `ldr rN, =sym` literal pool, bytes a NAKED function
    emits after its own `.size`, a NAKED label with no `.size` at all) -
    see patch_expected_target.py's set_function_sizes(). The build's own
    object is never touched."""
    out_o = BUILD_DIR / f"{name}_{start:08X}_base.o"
    shutil.copyfile(ROOT / "build" / "crashbandicootxs" / base_rel, out_o)
    run(["python3", str(ROOT / "tools" / "patch_expected_target.py"), "--base-object", str(out_o)])
    return out_o


def main():
    BUILD_DIR.mkdir(parents=True, exist_ok=True)
    categories = {}
    units = []

    # Files with a leftover raw pointer-arithmetic offset cast or raw
    # hardware address (see chunk_remaining_work.py's scan_cleanup_candidates
    # / its "Cleanup: raw pointer arithmetic in ..." issues) are matched
    # but not yet cleaned up per docs/workflow.md step 7. A matched unit
    # not in this set gets metadata.complete=True; one that is gets
    # False - objdiff/decomp.dev track this as a status independent of
    # match percentage, so a byte-exact-but-uncleaned file still shows
    # 100% matched while correctly not counting as "complete".
    needs_cleanup = {entry["file"] for entry in scan_cleanup_candidates() if entry["blocking"]}

    code_units = [(UNITS[i], UNITS[i + 1][0], None) for i in range(len(UNITS) - 1)]
    code_units += [(IWRAM_UNITS[i], IWRAM_UNITS[i + 1][0], IWRAM_CODE) for i in range(len(IWRAM_UNITS) - 1)]
    for (start, base_rel, category), end, source in code_units:
        if base_rel == HANDWRITTEN:
            continue
        if base_rel is None:
            name = f"raw_{start:08X}"
        else:
            name = Path(base_rel).stem

        target_o = build_target(name, start, end, source)
        unit = {
            "name": name,
            "target_path": str(target_o.relative_to(ROOT)),
        }
        metadata = {}
        if base_rel is not None:
            unit["base_path"] = str(build_base(name, start, base_rel).relative_to(ROOT))
            src_path = str(Path(base_rel).with_suffix(".c"))
            metadata["complete"] = src_path not in needs_cleanup
        if category is not None:
            metadata["progress_categories"] = [category]
            categories[category] = CATEGORY_NAMES.get(category, category.capitalize())
        if metadata:
            unit["metadata"] = metadata
        units.append(unit)

    data = data_units()
    units += data
    categories[DATA_CATEGORY] = CATEGORY_NAMES[DATA_CATEGORY]

    objdiff = {
        "$schema": "https://raw.githubusercontent.com/encounter/objdiff/main/config.schema.json",
        "build_target": False,
        "build_base": False,
        "progress_categories": [{"id": cid, "name": name} for cid, name in categories.items()],
        "units": units,
    }
    (ROOT / "objdiff.json").write_text(json.dumps(objdiff, indent=4) + "\n")
    print(f"Wrote objdiff.json with {len(units)} units, {len(categories)} categories")


if __name__ == "__main__":
    main()
